<?php
declare(strict_types=1);require dirname(__DIR__).'/core/bootstrap.php';
try{$c=nexus_config();$gw=nexus_world($_GET['world']??'');$season=nexus_season($_GET['season']??null);$id=(int)($_GET['id']??0);if($id<1)throw new InvalidArgumentException('invalid_club');$core=nexus_db($c,'core');$m=nexus_rows($core,'SELECT `SM Club ID` sm_club_id,`SM World Club ID` world_id,`Club Name` name FROM `IMC Game World Club Mapping` WHERE `Game World`=? AND `Club ID`=? LIMIT 1',[$gw,$id]);if(!$m)throw new InvalidArgumentException('club_not_found');$sm=(int)$m[0]['sm_club_id'];$db=nexus_db($c,nexus_target($c,$gw));$table=nexus_table($gw,'Match_Report');$w='(home_sm_club_id=? OR away_sm_club_id=?)';$p=[$sm,$sm];if($season!==null){$w.=' AND imc_season=?';$p[]=$season;}$rows=nexus_rows($db,'SELECT sm_fixture_id,competition_key,match_date,home_sm_club_id,home_name,away_sm_club_id,away_name,home_score,away_score,stadium_name,attendance,team_stats_json,players_json,events_json,home_manager_name,away_manager_name FROM `'.$table.'` WHERE '.$w.' ORDER BY match_date DESC,sm_fixture_id DESC',$p);
$sum=['played'=>0,'won'=>0,'drawn'=>0,'lost'=>0,'gf'=>0,'ga'=>0,'attendance_total'=>0,'attendance_matches'=>0,'attendance_max'=>0];$players=[];$opponents=[];
foreach($rows as $r){$home=(int)$r['home_sm_club_id']===$sm;$gf=(int)($home?$r['home_score']:$r['away_score']);$ga=(int)($home?$r['away_score']:$r['home_score']);$sum['played']++;$sum['gf']+=$gf;$sum['ga']+=$ga;if($gf>$ga)$sum['won']++;elseif($gf===$ga)$sum['drawn']++;else$sum['lost']++;if($r['attendance']!==null){$a=(int)$r['attendance'];$sum['attendance_total']+=$a;$sum['attendance_matches']++;$sum['attendance_max']=max($sum['attendance_max'],$a);}$opp=$home?$r['away_name']:$r['home_name'];if(!isset($opponents[$opp]))$opponents[$opp]=['opponent'=>$opp,'played'=>0,'won'=>0,'drawn'=>0,'lost'=>0,'gf'=>0,'ga'=>0];$o=&$opponents[$opp];$o['played']++;$o['gf']+=$gf;$o['ga']+=$ga;if($gf>$ga)$o['won']++;elseif($gf===$ga)$o['drawn']++;else$o['lost']++;unset($o);
 $pj=json_decode((string)($r['players_json']??''),true);if(is_array($pj)){foreach($pj as $pl){if(!is_array($pl))continue;$pid=(string)($pl['player_id']??$pl['id']??$pl['name']??'');if($pid==='')continue;$team=(string)($pl['team_id']??$pl['sm_club_id']??'');if($team!==''&&(int)$team!==$sm)continue;if(!isset($players[$pid]))$players[$pid]=['player_id'=>$pl['player_id']??$pl['id']??null,'name'=>$pl['player_name']??$pl['name']??'Player','appearances'=>0,'minutes'=>0,'goals'=>0,'assists'=>0,'rating_sum'=>0,'rating_count'=>0,'mom'=>0,'yellow'=>0,'red'=>0];$x=&$players[$pid];$x['appearances']++;$x['minutes']+=(int)($pl['minutes']??0);$x['goals']+=(int)($pl['goals']??0);$x['assists']+=(int)($pl['assists']??0);if(isset($pl['rating'])&&is_numeric($pl['rating'])){$x['rating_sum']+=(float)$pl['rating'];$x['rating_count']++;}$x['mom']+=(int)($pl['mom']??$pl['man_of_match']??0);$x['yellow']+=(int)($pl['yellow']??$pl['yellow_cards']??0);$x['red']+=(int)($pl['red']??$pl['red_cards']??0);unset($x);}}}
$sum['gd']=$sum['gf']-$sum['ga'];$sum['win_pct']=$sum['played']?round($sum['won']*100/$sum['played'],1):0;$sum['attendance_avg']=$sum['attendance_matches']?round($sum['attendance_total']/$sum['attendance_matches']):0;foreach($players as &$x){$x['rating']=$x['rating_count']?round($x['rating_sum']/$x['rating_count'],2):null;unset($x['rating_sum'],$x['rating_count']);}unset($x);usort($players,fn($a,$b)=>$b['appearances']<=>$a['appearances']);usort($opponents,fn($a,$b)=>$b['played']<=>$a['played']);nexus_out(['ok'=>true,'summary'=>$sum,'matches'=>$rows,'players'=>array_values($players),'h2h'=>array_values($opponents)]);}
catch(InvalidArgumentException $e){nexus_out(['ok'=>false,'error'=>$e->getMessage()],422);}catch(Throwable $e){nexus_out(['ok'=>false,'error'=>'club_data_error'],500);}
